type Stat = {
    id: string;
    value: string;
    suffix?: string;
    label: string;
    note: string;
    border: string;
};
const STATS: Stat[] = [
    { id: "01", value: "28", suffix: "k+", label: "Workflows completed", note: "this quarter", border: "" },
    {
        id: "02",
        value: "99.99",
        suffix: "%",
        label: "Platform uptime",
