        border: " art:border-t art:@min-[640px]/artemis:border-t-0 art:@min-[640px]/artemis:border-l art:@min-[1024px]/artemis:border-t-0 art:@min-[1024px]/artemis:border-l",
    },
    {
        id: "03",
        value: "42",
        suffix: "%",
        label: "Faster delivery",
        note: "from brief to launch",
        border: " art:border-t art:@min-[640px]/artemis:border-t art:@min-[1024px]/artemis:border-t-0 art:@min-[1024px]/artemis:border-l",
    },
    {
        id: "04",
