          <motion.header className="art:grid art:gap-6 art:@min-[768px]/artemis:grid-cols-[1.3fr_0.7fr] art:@min-[768px]/artemis:items-end" initial={{ opacity: 0, y: 18, filter: "blur(8px)" }} whileInView={reduce ? undefined : { opacity: 1, y: 0, filter: "blur(0px)" }} viewport={{ once: true, margin: "-80px" }} transition={{ duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
